# Which safety ECUs can each entry point reach? A flat design puts
# everything on one bus; a gateway forwards only routes in its table.
ENTRY = {"cellular": "telematics", "bluetooth": "head_unit",
         "obd_port": "diag_link"}
SAFETY = {"brakes": "chassis", "steering": "chassis", "engine": "powertrain"}

def reach(entry, routes):
    src = ENTRY[entry]
    return sorted(e for e, bus in SAFETY.items() if bus in routes.get(src, []))

flat = {s: ["chassis", "powertrain", "body"] for s in ENTRY.values()}
gated = {"telematics": ["body"],              # remote lock/unlock only
         "head_unit": ["body"],               # display, audio, climate
         "diag_link": ["chassis", "powertrain", "body"]}  # workshop

for name, routes in [("flat bus", flat), ("gateway", gated)]:
    for e in ENTRY:
        print(f"{name:8} {e:9} -> {reach(e, routes) or 'no safety ECU'}")

# Bitwise arbitration on a wired-AND bus: 0 (dominant) beats 1 (recessive).
# Each node sends its 11-bit identifier MSB first and listens as it sends.
def arbitrate(ids):
    contenders = set(ids)
    for bit in range(10, -1, -1):                 # ID-10 first
        sent = {i: (i >> bit) & 1 for i in contenders}
        bus = min(sent.values())                  # any 0 pulls the bus to 0
        lost = {i for i, b in sent.items() if b != bus}
        if lost:
            print(f"bit {bit:2}: bus={bus}, dropped out: "
                  + ", ".join(f"0x{i:03X}" for i in sorted(lost)))
        contenders -= lost
    return contenders.pop()

winner = arbitrate([0x244, 0x0C4, 0x0C8])
print(f"winner: 0x{winner:03X} (lowest identifier = highest priority)")

