# Fault confinement from the CAN 2.0 spec, for one transmitter:
# +8 to the transmit error count (TEC) per error, -1 per clean frame.
# TEC >= 128: error passive. TEC >= 256: bus off (node goes silent).
def state(tec):
    return "bus off" if tec >= 256 else "error passive" if tec >= 128 else "error active"

def run(events, alert_after=2):
    tec, streak, log = 0, 0, []
    for n, ev in enumerate(events, 1):
        if ev == "error":
            tec, streak = tec + 8, streak + 1
        else:
            tec, streak = max(tec - 1, 0), 0
        if streak == alert_after:
            log.append(f"frame {n}: IDS alert, {streak} errors in a row on this ID")
        if state(tec) != "error active" and (not log or state(tec) not in log[-1]):
            log.append(f"frame {n}: TEC={tec} -> {state(tec)}")
        if tec >= 256:
            break
    return log

for name, events in [("noisy wire, 1 error per 10 frames", (["ok"] * 9 + ["error"]) * 20),
                     ("an error forced on every transmission", ["error"] * 40)]:
    print(name + ":")
    for line in run(events) or ["stays error active, no alert"]:
        print("  " + line)

import random
random.seed(7)
PERIOD_MS = {0x0C4: 10, 0x244: 20, 0x3E8: 100}   # learned from clean traffic

def traffic(ms, inject=None):
    frames = []
    for cid, p in PERIOD_MS.items():
        t = random.uniform(0, p)
        while t < ms:
            frames.append((t, cid, "R"))
            t += p + random.uniform(-0.5, 0.5)      # normal jitter
    if inject:                                     # (start, stop, id, every)
        a, b, cid, every = inject
        frames += [(a + k * every, cid, "T") for k in range(int((b - a) / every))]
    return sorted(frames)

def ids(frames):
    last, alerts = {}, []
    for t, cid, truth in frames:
        if cid not in PERIOD_MS:
            alerts.append((t, cid, truth, "unknown ID"))
        elif cid in last and t - last[cid] < 0.5 * PERIOD_MS[cid]:
            alerts.append((t, cid, truth, "too soon"))
        last[cid] = t
    return alerts

for name, inj in [("clean", None), ("spoof 0x0C4 every 1 ms", (300, 400, 0x0C4, 1.0)),
                  ("fuzz unknown ID 0x7A1", (300, 310, 0x7A1, 0.5))]:
    f = traffic(1000, inj)
    a = ids(f)
    injected = sum(1 for x in f if x[2] == "T")
    caught = sum(1 for x in a if x[2] == "T")
    false = sum(1 for x in a if x[2] == "R")
    print(f"{name:24} frames={len(f):4} injected={injected:3} "
          f"flagged={caught:3} false alarms={false}")

# Time of flight: radio covers about 0.3 m per nanosecond. A relay can only
# ADD delay, so measuring the round trip puts an upper bound on distance.
C = 0.299792458                        # metres per nanosecond

def rtt_ns(distance_m, relay_extra_ns=0.0):
    return 2 * distance_m / C + relay_extra_ns

def bound_m(rtt):                      # assumes the fob's reply time is known
    return rtt * C / 2                 # and subtracted (here: zero)

cases = {
    "owner at the door, 1.5 m": rtt_ns(1.5),
    "relay, fob 30 m away":     rtt_ns(1.5) + rtt_ns(30, relay_extra_ns=2 * 20),
}
for name, t in cases.items():
    old = "open" if t <= 35_000 else "refuse"          # accepts up to 35 us
    new = "open" if bound_m(t) <= 2.0 else "refuse"    # bound of 2 m
    print(f"{name:26} RTT {t:7.1f} ns | bound {bound_m(t):5.1f} m | "
          f"timing-blind car: {old:6} | distance bounding: {new}")

# Gateway policy for the "key validated" frame (toy model of the 2023 case).
# Each bus event: (time_ms, kind, detail).
def gateway(events, policy):
    last_error = -10_000
    for t, kind, detail in events:
        if kind == "error_frame":
            last_error = t
        elif kind == "key_ok":
            if policy == "forward all":
                print(f"  t={t}: forwarded to powertrain bus")
            elif policy == "quiet bus" and t - last_error < 500:
                print(f"  t={t}: DROPPED, bus errors {t - last_error} ms ago; log event")
            elif policy == "mac" and detail != "valid MAC":
                print(f"  t={t}: DROPPED, authenticator check failed; log event")
            else:
                print(f"  t={t}: forwarded to powertrain bus")

owner = [(0, "key_ok", "valid MAC")]
# Injector overpowers the bus: real ECUs' frames fail, errors pile up.
thief = [(0, "error_frame", ""), (40, "error_frame", ""),
         (120, "key_ok", "no MAC")]
for policy in ["forward all", "quiet bus", "mac"]:
    print(policy, "| owner:"); gateway(owner, policy)
    print(policy, "| thief:"); gateway(thief, policy)

# Charging station management system (CSMS) admission rules, following the
# OCPP security profiles: 1 = basic auth, no TLS; 2 = TLS + basic auth;
# 3 = TLS with client certificates on both sides.
KNOWN = {"CS-001": {"best_profile_seen": 3}, "CS-002": {"best_profile_seen": 2}}

def admit(station, profile, password=None, client_cert_ok=False, private_vpn=False):
    rec = KNOWN.get(station)
    if rec is None:
        return "reject: unknown station id"
    if profile < rec["best_profile_seen"]:
        return f"reject: downgrade from profile {rec['best_profile_seen']}"
    if profile == 1 and not private_vpn:
        return "reject: profile 1 on an untrusted network"
    if profile == 2 and (password is None or len(password) < 16):
        return "reject: password shorter than 16 characters"
    if profile == 3 and not client_cert_ok:
        return "reject: client certificate invalid"
    rec["best_profile_seen"] = max(rec["best_profile_seen"], profile)
    return f"accept (profile {profile})"

print(admit("CS-001", 3, client_cert_ok=True))
print(admit("CS-001", 2, password="x" * 20))         # attacker forces a fallback
print(admit("CS-002", 2, password="hunter2"))
print(admit("CS-002", 2, password="Vq7#pL2z!mR9xT4w"))
print(admit("CS-999", 3, client_cert_ok=True))

