# ISO/SAE 21434 TARA, attack-potential approach (example values from the
# standard's informative annex, as reproduced by Unger et al., 2023).
TIME = {"<=1 day": 0, "<=1 week": 1, "<=1 month": 4, "<=6 months": 17, ">6 months": 19}
EXPERTISE = {"layman": 0, "proficient": 3, "expert": 6, "multiple experts": 8}
KNOWLEDGE = {"public": 0, "restricted": 3, "confidential": 7, "strictly confidential": 11}
WINDOW = {"unlimited": 0, "easy": 1, "moderate": 4, "difficult": 10}
EQUIPMENT = {"standard": 0, "specialized": 4, "bespoke": 7, "multiple bespoke": 9}

def feasibility(potential):
    if potential <= 13: return "high"
    if potential <= 19: return "medium"
    if potential <= 24: return "low"
    return "very low"

RISK = {"negligible": [1, 1, 1, 1], "moderate": [1, 2, 2, 3],
        "major": [1, 2, 3, 4], "severe": [2, 3, 4, 5]}
COLS = ["very low", "low", "medium", "high"]

def tara(name, impact, t, ex, kn, wi, eq):
    p = TIME[t] + EXPERTISE[ex] + KNOWLEDGE[kn] + WINDOW[wi] + EQUIPMENT[eq]
    f = feasibility(p)
    print(f"{name:40} potential {p:2} -> {f:8} x {impact:8} = risk {RISK[impact][COLS.index(f)]}")

# Threat: spoofed "key validated" frame lets a thief drive the car away.
tara("design phase: first discovery", "severe",
     "<=1 month", "expert", "restricted", "easy", "specialized")
tara("after a device is sold to thieves", "severe",
     "<=1 day", "layman", "public", "easy", "specialized")
tara("same, with authenticated key frames", "severe",
     ">6 months", "multiple experts", "strictly confidential", "easy", "bespoke")
